-- Cluster: an entity (record) register of farmer clusters — groups of smallholders
-- farming one crop together in a woreda under a government cluster programme.
-- Hand-written (unlike g2p_register_definitions.sql, which scripts/build_seed_sql.py
-- generates for the CropSown activity register).
--
-- The cluster code is the functional_record_id, entered by staff: this registry
-- runs without the ID generator. Crop, agro-ecological zone and water source are
-- Master Data code lists read live by the dropdowns. New clusters are registered
-- through the cluster intake form; edits are change requests. Both are approved
-- in AWE (awe-integration/ binds the policies, awe_meta_data/ seeds them).

INSERT INTO "public"."g2p_register_definitions" ("register_id","register_mnemonic","register_subject","register_description","master_register_id","register_rank","functional_id_generation_required","register_purpose","program_id","program_mnemonic","register_icon","has_image","dedup_is_enabled","dedup_threshold_score","completion_score_required","outgest_applicable","requires_registrant_authentication","registrant_authentication_validity_days","registrant_re_auth_warning_days_before") VALUES
('c5000000-0000-4000-8000-0000000c0001','Cluster','Clusters','Farmer clusters: smallholders farming one crop together under a cluster programme',NULL,2,'FALSE','REGISTER',NULL,NULL,NULL,'FALSE','FALSE',0,'FALSE','FALSE','FALSE',730,30)
ON CONFLICT DO NOTHING;

